/* Version 2: keeps v1 question IDs and localStorage key so existing progress survives. */
const builtInCount=questions.length;
state.custom=Array.isArray(state.custom)?state.custom:[];
state.reviews=state.reviews||{};state.causes=state.causes||{};state.labs=state.labs||{};state.settings=state.settings||{daily:20};
state.activePractice=state.activePractice||null;
state.custom=state.custom.filter(q=>validQuestion(q)&&q.id.startsWith('custom-')&&!questions.some(x=>x.id===q.id));questions.push(...state.custom);
for(const [id,w] of Object.entries(state.wrong))if(!state.reviews[id])state.reviews[id]={streak:w.mastered?2:0,due:Date.now(),last:0};
const legacy=window.legacyV1;
navs.splice(2,0,['bank','▦','题库管理']);navs.splice(navs.length-1,0,['lab','⌘','交互实操'],['analytics','▥','学习分析']);
let filterDifficulty='all',filterStatus='all',practiceCount=20,practiceOrder='random',bankPage=0,wrongMode='pending',cardSearch='',draftBank=null,reportFilter='all',submittedOnce=false;
const DAY=86400000;const safeObject=x=>x&&typeof x==='object'&&!Array.isArray(x);
function validQuestion(q){return q&&typeof q.id==='string'&&/^[a-z0-9-]{1,60}$/.test(q.id)&&Number.isInteger(q.m)&&q.m>=0&&q.m<6&&['单选','多选','判断'].includes(q.type)&&typeof q.stem==='string'&&q.stem.trim().length>=5&&q.stem.length<=3000&&Array.isArray(q.options)&&q.options.length>=2&&q.options.length<=6&&q.options.every(s=>typeof s==='string'&&s.trim()&&s.length<=2000)&&new Set(q.options).size===q.options.length&&Array.isArray(q.answer)&&q.answer.length>=1&&new Set(q.answer).size===q.answer.length&&q.answer.every(i=>Number.isInteger(i)&&i>=0&&i<q.options.length)&&(q.type==='多选'||q.answer.length===1)&&(q.type!=='判断'||q.options.length===2)&&typeof q.explain==='string'&&q.explain.trim().length>=5&&q.explain.length<=5000}
function shuffled(arr){let a=[...arr];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function latestMap(){let map={};state.history.forEach(h=>map[h.id]=h);return map}
function dueIds(){return Object.keys(state.reviews).filter(id=>qby(id)&&state.reviews[id].due<=Date.now())}
function selectOptions(values,value){return values.map(([v,label])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}
function moduleSelect(){return `<select aria-label="筛选模块" onchange="filterModule=this.value;cardIndex=0;flipped=false;bankPage=0;render()">${selectOptions([['all','全部模块'],...modules.map((m,i)=>[i,m[0]])],filterModule)}</select>`}
function go(p){if(location.hash.slice(1)===p){page=p;render()}else location.hash=p}
function render(){page=location.hash.slice(1)||'home';if(!navs.some(n=>n[0]===page))page='home';$('#nav').innerHTML=navs.map(n=>`<a class="${page===n[0]?'active':''}" href="#${n[0]}"><span>${n[1]}</span>${n[2]}</a>`).join('');({home,practice,wrong,cards,exam,cases:casesPage,guide,bank,lab,analytics})[page]();document.title='训练师研习室 · '+navs.find(n=>n[0]===page)[2]}
function home(){legacy.home();let html=$('#app').innerHTML;html=html.replace('六个学习模块 · '+questions.length+' 道原创练习 · 5 个实操案例',`六个学习模块 · ${questions.length} 道题 · 5 项交互实操`).replace('① 学习 3 张速记卡','① 学习 3 张速记卡').replace('② 完成 10 道随机练习',`② 完成 ${state.settings.daily} 道每日训练`);$('#app').innerHTML=html+`<section class="card" style="margin-top:24px"><div class="row"><div><span class="eyebrow">SMART REVIEW</span><h2>今天，先补上最重要的一块</h2><p class="muted">${dueIds().length} 题到期复习 · ${state.activePractice?'有一组未结束练习':'优先安排未做题与薄弱模块'} · 原有学习记录已保留</p></div><button class="primary" onclick="startSmart()">智能安排 ${state.settings.daily} 题 →</button></div><div class="actions"><button onclick="go('analytics')">查看薄弱点</button><button onclick="go('lab')">做一次真实操作</button>${state.activePractice?'<button onclick="resumePractice()">继续上次练习</button>':''}</div></section>`}
function filteredQuestions(){let latest=latestMap();return questions.filter(q=>(filterModule==='all'||q.m==filterModule)&&(filterType==='all'||q.type===filterType)&&(filterDifficulty==='all'||q.difficulty===filterDifficulty)&&(!filterText||`${q.id} ${q.stem} ${q.explain} ${q.tag} ${q.options.join(' ')}`.toLowerCase().includes(filterText.toLowerCase()))&&(filterStatus==='all'||filterStatus==='new'&&!latest[q.id]||filterStatus==='wrong'&&state.wrong[q.id]&&!state.wrong[q.id].mastered||filterStatus==='star'&&state.stars.includes(q.id)||filterStatus==='custom'&&q.id.startsWith('custom-')))}
function pool(){return filteredQuestions()}
function filterBar(){return `<div class="toolbar">${moduleSelect()}<select aria-label="题型" onchange="filterType=this.value;bankPage=0;render()">${selectOptions([['all','全部题型'],['单选','单选'],['多选','多选'],['判断','判断']],filterType)}</select><select aria-label="难度" onchange="filterDifficulty=this.value;bankPage=0;render()">${selectOptions([['all','全部难度'],['基础','基础'],['进阶','进阶'],['应用','应用']],filterDifficulty)}</select><select aria-label="题目状态" onchange="filterStatus=this.value;bankPage=0;render()">${selectOptions([['all','全部状态'],['new','未做题'],['wrong','待巩固'],['star','已收藏'],['custom','自导入']],filterStatus)}</select><input id="search" type="search" placeholder="搜索题干、解析、关键词" value="${esc(filterText)}" oninput="filterText=this.value;bankPage=0;updateSearch()"><button onclick="filterModule=filterType=filterDifficulty=filterStatus='all';filterText='';bankPage=0;render()">清除筛选</button></div>`}
function updateSearch(){if($('#qcount'))$('#qcount').textContent=pool().length;if(page==='bank')drawBankRows()}
function practice(){if(session&&!session.exam){drawQuestion();return}$('#app').innerHTML=heading('题目练习，让每一题都有效。','支持筛选、顺序与随机练习；进度自动保存，可跳题、回看和继续。')+filterBar()+`<section class="card"><div class="row"><div><h2>当前范围 <span id="qcount">${pool().length}</span> 题</h2><p class="muted">${builtInCount} 道内置题，另有 ${state.custom.length} 道自导入题。60 道为独立标记的计算变式。</p></div><span class="pill">题库 v2 · 原创训练</span></div><div class="toolbar"><label>每组题量 <select id="practiceN" aria-label="练习题量" onchange="practiceCount=Number(this.value)">${selectOptions([[10,'10题'],[20,'20题'],[50,'50题'],[100,'100题'],[9999,'当前范围全部']],practiceCount)}</select></label><label>出题顺序 <select aria-label="出题顺序" onchange="practiceOrder=this.value">${selectOptions([['random','随机'],['ordered','题库顺序']],practiceOrder)}</select></label><button class="primary" onclick="startFiltered()">开始筛选练习 →</button><button onclick="startSmart()">智能训练</button>${state.activePractice?'<button onclick="resumePractice()">继续上次练习</button>':''}</div></section><div class="cards" style="margin-top:24px">${modules.map((m,i)=>`<section class="card"><span class="pill">${m[2]}</span><h2 style="margin-top:15px">${m[0]}</h2><p class="muted">${m[1]} · ${questions.filter(q=>q.m===i).length} 题</p><button onclick="startPractice('${i}',20)">练习 20 题 →</button></section>`).join('')}</div><div class="actions"><button onclick="startList(state.stars,'收藏练习')">收藏练习（${state.stars.length}）</button><button onclick="startList(dueIds(),'到期复习')">到期复习（${dueIds().length}）</button></div>`}
function startFiltered(){let qs=pool();startList((practiceOrder==='random'?shuffled(qs):qs).slice(0,practiceCount).map(q=>q.id),'筛选练习')}
function startPractice(m,n){startList(shuffled(questions.filter(q=>m==='all'||q.m==m)).slice(0,n).map(q=>q.id),'专项练习')}
function startSmart(){let latest=latestMap(),weak=moduleStats().sort((a,b)=>a.accuracy-b.accuracy)[0]?.m||0;let ids=[...shuffled(dueIds()),...shuffled(questions.filter(q=>state.wrong[q.id]&&!state.wrong[q.id].mastered).map(q=>q.id)),...shuffled(questions.filter(q=>q.m===weak&&!latest[q.id]).map(q=>q.id)),...shuffled(questions.filter(q=>!latest[q.id]).map(q=>q.id)),...shuffled(questions.map(q=>q.id))];startList([...new Set(ids)].slice(0,state.settings.daily),'智能训练：到期 → 错题 → 薄弱 → 未做')}
function startList(ids,title){ids=[...new Set(ids)].filter(qby);if(!ids.length){toast('当前没有符合条件的题目');return}if(state.activeExam){toast('请先完成正在计时的模拟考试');go('exam');return}if(state.activePractice&&!confirm('开始新一组将替换尚未结束的练习进度，已提交的做题记录会保留。继续？'))return;session={ids,title,answers:{},exam:false,submitted:{},pos:0,started:Date.now()};pos=0;selection=[];revealed=false;result=null;state.activePractice=session;save();go('practice')}
function resumePractice(){if(!state.activePractice){toast('没有未完成练习');return}session=state.activePractice;session.submitted=session.submitted||{};pos=session.pos||0;selection=session.answers[session.ids[pos]]||[];revealed=!!session.submitted[session.ids[pos]];go('practice')}
function persistSession(){session.pos=pos;if(session.exam)state.activeExam=session;else state.activePractice=session;save()}
function displayedOrder(q){return session.orders?.[q.id]||q.options.map((_,i)=>i)}
function letterAnswer(q,ans){let order=displayedOrder(q);return order.map((idx,i)=>ans.includes(idx)?'ABCDEF'[i]:null).filter(Boolean).join('、')}
function drawQuestion(){let q=qby(session.ids[pos]);if(!q){toast('题目不存在，请返回题库');session=null;state.activePractice=null;save();practice();return}selection=[...(session.answers[q.id]||[])];revealed=!session.exam&&!!session.submitted?.[q.id];let order=displayedOrder(q);let submitted=revealed;let ok=eq(selection,q.answer);let done=session.exam?Object.values(session.answers).filter(x=>x.length).length:Object.keys(session.submitted||{}).length;
$('#app').innerHTML=heading(session.exam?'模拟考试进行中':session.title,session.exam?'答题自动保存；交卷后统一解析，关闭页面不会暂停计时。':'先自己判断，再查看解析。上一题、跳题、收藏与笔记都可以使用。')+`<div class="row"><span class="pill">${modules[q.m][0]} · ${q.type} · ${esc(q.difficulty||'基础')}</span><span>${session.exam?'<b id="timer"></b>　':''}${pos+1}/${session.ids.length} · 已${session.exam?'作答':'提交'} ${done}</span></div><div class="progress"><div style="width:${pct(done,session.ids.length)}%"></div></div><section class="card" style="margin-top:22px"><div class="row"><span class="muted">${esc(q.id)} · ${esc(q.source||'原创训练')} · ${esc(q.tag||'')}</span><button onclick="${session.exam?`toggleFlag('${q.id}')`:`star('${q.id}')`}">${session.exam?(session.flags?.includes(q.id)?'⚑ 已标记':'⚐ 标记稍后检查'):(state.stars.includes(q.id)?'★ 已收藏':'☆ 收藏')}</button></div><h2 class="question">${esc(q.stem)}</h2>${q.type==='多选'?'<p class="muted">多选：全部选对才计分，漏选或多选均不得分。</p>':''}<div class="options">${order.map((idx,i)=>`<button class="option ${selection.includes(idx)?'selected':''} ${submitted&&q.answer.includes(idx)?'correct':''} ${submitted&&selection.includes(idx)&&!q.answer.includes(idx)?'wrong':''}" aria-pressed="${selection.includes(idx)}" onclick="choose(${idx})" ${submitted?'disabled':''}><b>${'ABCDEF'[i]}</b>${esc(q.options[idx])}</button>`).join('')}</div>${submitted?`<div class="explain ${ok?'':'error'}"><b>${ok?'回答正确':'本题需要巩固'}</b><p>正确答案：${letterAnswer(q,q.answer)}</p>${esc(q.explain)}</div><div class="row"><label for="qnote">我的错因 / 笔记</label>${!ok?causeSelect(q.id):''}</div><textarea id="qnote" placeholder="记住判断过程，而不是答案字母……" oninput="state.notes['${q.id}']=this.value;save()">${esc(state.notes[q.id]||'')}</textarea>`:''}<div class="actions"><button onclick="move(-1)" ${pos===0?'disabled':''}>← 上一题</button>${session.exam?'':!submitted?'<button class="primary" onclick="submitPractice()">提交答案</button>':''}<button class="${submitted||session.exam?'primary':''}" onclick="move(1)" ${pos===session.ids.length-1?'disabled':''}>${!submitted&&!session.exam?'跳过 / 下一题':'下一题 →'}</button>${session.exam?'<button onclick="finishExam(false)">交卷</button>':'<button onclick="finishPractice()">完成本组</button><button onclick="persistSession();session=null;practice()">保存并返回</button>'}</div></section><section class="card" style="margin-top:20px"><h3>答题卡 <small class="muted">绿：已作答　⚑：待检查</small></h3><div class="answer-grid">${session.ids.map((id,i)=>`<button class="${(session.exam?session.answers[id]?.length:session.submitted?.[id])?'done':''} ${i===pos?'current':''}" aria-label="跳到第${i+1}题" onclick="jump(${i})">${i+1}${session.flags?.includes(id)?'⚑':''}</button>`).join('')}</div></section>`;if(session.exam)tick()}
function choose(i){if(!session||(!session.exam&&session.submitted?.[session.ids[pos]]))return;let q=qby(session.ids[pos]);let a=session.answers[q.id]||[];session.answers[q.id]=q.type==='多选'?(a.includes(i)?a.filter(v=>v!==i):[...a,i]):[i];persistSession();drawQuestion()}
function recordAnswer(q,ans,mode){let ok=eq(ans,q.answer),now=Date.now();state.history.push({id:q.id,ok,at:now,mode,answer:[...ans]});let w=state.wrong[q.id];if(!ok){state.wrong[q.id]={...(w||{}),count:(w?.count||0)+1,mastered:false,last:now,answer:[...ans]};state.reviews[q.id]={streak:0,due:now+DAY,last:now}}else if(w){let r=state.reviews[q.id]||{streak:0,last:0};let streak=r.streak||0;if(now-(r.last||0)>=20*60*60*1000||streak===0)streak++;state.reviews[q.id]={streak,due:now+[1,3,7,14,30][Math.min(streak-1,4)]*DAY,last:now};w.mastered=streak>=2}activity();return ok}
function submitPractice(){if(!session||session.exam)return;let q=qby(session.ids[pos]);if(session.submitted[q.id])return;let ans=session.answers[q.id]||[];if(!ans.length){toast('请先选择答案');return}recordAnswer(q,ans,'practice');session.submitted[q.id]=true;persistSession();drawQuestion()}
function nextPractice(){move(1)}
function jump(i){pos=Math.max(0,Math.min(session.ids.length-1,i));persistSession();drawQuestion()}
function move(d){jump(pos+d)}
function finishPractice(){let s=session,submitted=Object.keys(s.submitted),remaining=s.ids.length-submitted.length;if(remaining&&!confirm(`还有${remaining}题未提交，结束本组？未提交题不会算入正确率。`))return;let correct=submitted.filter(id=>eq(s.answers[id],qby(id).answer)).length;state.activePractice=null;session=null;save();$('#app').innerHTML=heading('这一组，练完了。','练习正确率仅统计已提交题目，未提交题不计为答错。')+`<section class="card empty"><div class="score">${pct(correct,submitted.length)}<small>%</small></div><p>答对 ${correct}/${submitted.length} · 未提交 ${remaining} 题</p><div class="actions" style="justify-content:center"><button class="primary" onclick="go('wrong')">复习错题</button><button onclick="practice()">继续练习</button><button onclick="go('analytics')">查看学习分析</button></div></section>`}
function star(id){state.stars=state.stars.includes(id)?state.stars.filter(x=>x!==id):[...state.stars,id];save();drawQuestion()}
function causeSelect(id){return `<select aria-label="错因分类" onchange="state.causes['${id}']=this.value;save()">${selectOptions([['','选择错因'],['概念不清','概念不清'],['审题失误','审题失误'],['公式混淆','公式混淆'],['操作不熟','操作不熟'],['遗漏条件','遗漏条件']],state.causes[id]||'')}</select>`}
function wrong(){let all=Object.keys(state.wrong).filter(id=>qby(id)),ids=all.filter(id=>(filterModule==='all'||qby(id).m==filterModule)&&(wrongMode==='all'||wrongMode==='pending'&&!state.wrong[id].mastered||wrongMode==='mastered'&&state.wrong[id].mastered||wrongMode==='due'&&state.reviews[id]?.due<=Date.now()));ids.sort((a,b)=>state.wrong[b].count-state.wrong[a].count);windowWrongIds=ids;$('#app').innerHTML=heading('错题复习，按节奏巩固。','答错后次日复习；答对按1、3、7、14、30天延长间隔。至少隔20小时的两次答对，自动标记掌握。')+`<div class="toolbar">${moduleSelect()}<select aria-label="错题范围" onchange="wrongMode=this.value;wrong()">${selectOptions([['pending','待巩固'],['due','到期复习'],['mastered','已掌握'],['all','全部错题']],wrongMode)}</select><button class="primary" onclick="startList(windowWrongIds,'错题重练')">重练当前 ${ids.length} 题</button><button onclick="exportWrong()">导出错题 CSV</button></div><p class="muted">累计错题 ${all.length} · 到期 ${dueIds().length} · 当前 ${ids.length}。也可手动调整掌握状态。</p>${ids.length?ids.map(id=>{let q=qby(id),w=state.wrong[id],r=state.reviews[id];return `<section class="card" style="margin-bottom:15px"><div class="row"><span class="pill">${w.mastered?'已掌握':'待巩固'} · 错 ${w.count} 次 · ${r?.due<=Date.now()?'已到期':'复习日 '+new Date(r?.due||Date.now()).toLocaleDateString('zh-CN')}</span>${causeSelect(id)}</div><h3 style="margin-top:15px">${esc(q.stem)}</h3><details><summary>展开答案、解析与笔记</summary><p>${q.answer.map(i=>esc(q.options[i])).join('；')}</p><p class="note">${esc(q.explain)}</p><textarea aria-label="错题笔记" oninput="state.notes['${id}']=this.value;save()">${esc(state.notes[id]||'')}</textarea></details><div class="actions"><button onclick="startList(['${id}'],'单题巩固')">再练一次</button><button onclick="toggleMastered('${id}')">${w.mastered?'重新加入待巩固':'手动标记掌握'}</button></div></section>`}).join(''):'<section class="card empty"><h2>当前范围没有错题</h2><p class="muted">可以切换到“全部错题”，或去做一组新题。</p><button onclick="go(\'practice\')">去练习</button></section>'}`}
let windowWrongIds=[];
function toggleMastered(id){let w=state.wrong[id];w.mastered=!w.mastered;state.reviews[id]={streak:w.mastered?2:0,due:w.mastered?Date.now()+7*DAY:Date.now(),last:Date.now()};save();wrong()}
function downloadFile(name,data,type='application/json'){let url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportWrong(){let rows=[['题号','模块','题目','正确答案','解析','错题次数','掌握状态','错因','笔记'],...Object.keys(state.wrong).filter(qby).map(id=>{let q=qby(id),w=state.wrong[id];return[id,modules[q.m][0],q.stem,q.answer.map(i=>q.options[i]).join('；'),q.explain,w.count,w.mastered?'已掌握':'待巩固',state.causes[id]||'',state.notes[id]||'']})];downloadFile('错题复习-'+today()+'.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function cards(){legacy.cards();$('#app').insertAdjacentHTML('afterbegin',`<div class="toolbar"><input aria-label="速记搜索" placeholder="搜索速记卡，如：标注" value="${esc(cardSearch)}" oninput="cardSearch=this.value;searchCards()"><button onclick="printCards()">打印全部速记</button></div><div id="cardMatches"></div>`);searchCards()}
function searchCards(){let box=$('#cardMatches');if(!box)return;let ids=facts.map((f,i)=>i).filter(i=>facts[i].join(' ').includes(cardSearch));box.innerHTML=cardSearch?`<div class="tabs">${ids.map(i=>`<button onclick="filterModule='all';cardIndex=${i};flipped=true;cardSearch='';cards()">${esc(facts[i][1])}</button>`).join('')||'<p>没有匹配的要点</p>'}</div>`:''}
function printCards(){printDocument('要点速记',facts.map(f=>`<h2>${esc(f[1])}</h2><p>${esc(f[2])}</p><p>${esc(f[4])}</p><p><b>${esc(f[5])}</b></p>`).join(''))}
function printDocument(title,body){let w=window.open('','_blank');if(!w){toast('请允许打印窗口弹出');return}w.document.write(`<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><title>${esc(title)}</title><style>body{font:15px/1.8 sans-serif;max-width:900px;margin:40px auto}h2{break-after:avoid}p{break-inside:avoid}@media print{button{display:none}}</style></head><body><button onclick="window.print()">打印 / 保存PDF</button><h1>${esc(title)}</h1>${body}</body></html>`);w.document.close()}
